import React from 'react';

const TABS = [
  { id:'home',      icon:'◎', label:'Hem' },
  { id:'checkin',   icon:'◈', label:'Check-in' },
  { id:'history',   icon:'◫', label:'Historik' },
  { id:'breathing', icon:'◯', label:'Andning' },
];

export default function Nav({ page, setPage }) {
  return (
    <>
      {/* Top */}
      <div style={{ position:'fixed', top:0, left:0, right:0, zIndex:100, display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 24px', height:56, background:'rgba(12,12,14,0.7)', backdropFilter:'blur(28px) saturate(1.5)', borderBottom:'1px solid rgba(255,255,255,0.07)' }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.18em', color:'rgba(242,240,235,0.35)', textTransform:'uppercase' }}>
          KBT · Mental health
        </div>
        <div style={{ fontSize:17, fontWeight:800, letterSpacing:'-0.04em', color:'#f2f0eb' }}>SPIRAL</div>
      </div>

      {/* Bottom tab — liquid glass */}
      <div style={{ position:'fixed', bottom:16, left:16, right:16, zIndex:100, display:'flex', alignItems:'stretch', height:60, background:'linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)', backdropFilter:'blur(40px) saturate(1.5)', borderRadius:22, border:'1px solid rgba(255,255,255,0.12)', boxShadow:'0 8px 40px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.12)' }}>
        {TABS.map(tab => (
          <button key={tab.id} onClick={()=>setPage(tab.id)}
            style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:3, background:'none', border:'none', borderRadius:18, transition:'all .25s', position:'relative', overflow:'hidden' }}>
            {page === tab.id && (
              <div style={{ position:'absolute', inset:4, background:'rgba(255,255,255,0.1)', borderRadius:14, border:'1px solid rgba(255,255,255,0.1)' }} />
            )}
            <span style={{ fontSize:15, color: page===tab.id ? '#f2f0eb' : 'rgba(242,240,235,0.3)', transition:'all .25s', position:'relative', zIndex:1, transform: page===tab.id ? 'scale(1.1)' : 'scale(1)' }}>{tab.icon}</span>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:7, letterSpacing:'0.12em', textTransform:'uppercase', color: page===tab.id ? 'rgba(242,240,235,0.7)' : 'rgba(242,240,235,0.2)', position:'relative', zIndex:1 }}>{tab.label}</span>
          </button>
        ))}
      </div>
    </>
  );
}
